def solve(grid):
    # Count islands (4-directionally connected 1s) in a possibly jagged grid.
    if not grid:
        return 0
    n = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n:
                continue
            if y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            # push 4 neighbours
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))
    count = 0
    for i, row in enumerate(grid):
        for j in range(len(row)):
            if not visited[i][j] and row[j] == 1:
                dfs(i, j)
                count += 1
    return count

