{"task_id": "T25", "code": "def solve(matrix):
    """Return integer determinant of a square matrix (list of lists).
    Uses the Bareiss algorithm which performs exact integer arithmetic.
    An empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Ensure square (assume input is valid per spec)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Work on a copy of integers
    A = [list(map(int, row)) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivoting if current pivot is zero
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        pivot = A[k][k]
        # If previous pivot (denominator) is zero, determinant is zero
        if k > 0 and A[k - 1][k - 1] == 0:
            return 0
        denom = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update: exact division
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // denom
        for i in range(k + 1, n):
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]
