from fractions import Fraction

def solve(matrix):
    """Compute determinant of a square integer matrix using exact fraction Gaussian elimination.
    Returns an int. Empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # copy as Fractions
    A = [[Fraction(int(x)) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det = -det
        pivot_val = A[i][i]
        det *= pivot_val
        # normalize row i
        for j in range(i, n):
            A[i][j] /= pivot_val
        # eliminate below
        for k in range(i+1, n):
            factor = A[k][i]
            if factor != 0:
                for j in range(i, n):
                    A[k][j] -= factor * A[i][j]
    # det is product of pivots (already multiplied) which is Fraction
    return int(det)

def solve(lst):
