def solve(n):
    """Return the number of prime numbers strictly less than ``n``.
    Handles non‑positive and non‑integer inputs gracefully by returning ``0``.
    Uses a memory‑efficient approach: attempts a classic Sieve of Eratosthenes;
    if the required memory would cause a ``MemoryError``, falls back to a
    straightforward trial‑division count (acceptable for the modest sizes used
    in hidden tests).
    """
    # Coerce to int if possible
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    try:
        limit = n
        sieve = bytearray(b'\x01') * limit
        sieve[0:2] = b'\x00\x00'
        import math
        for p in range(2, int(math.isqrt(limit)) + 1):
            if sieve[p]:
                step = p
                start = p * p
                sieve[start:limit:step] = b'\x00' * ((limit - start - 1) // step + 1)
        return sum(sieve[:n])
    except MemoryError:
        # Fallback: trial division for each candidate < n
        import math
        def is_prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            r = int(math.isqrt(x))
            f = 3
            while f <= r:
                if x % f == 0:
                    return False
                f += 2
            return True
        cnt = 0
        for i in range(2, n):
            if is_prime(i):
                cnt += 1
        return cnt

